let audioProc: ReturnType<typeof spawn> | null = null;
let audioQueue: Buffer[] = [];
let audioQueuedBytes = 0;
/** ~0.5 с звука float32 стерео (384000 Б/с) — защита от переполнения */
const AUDIO_QUEUE_CAP = 192_000;

function audioHelperPath(): string {
    const dir = join(app.getPath("userData"), "p2pstream");
    mkdirSync(dir, { recursive: true });
    const exePath = join(dir, "p2paudio.exe");
    const buf = Buffer.from(P2P_AUDIO_EXE_B64, "base64");
    try {
        if (statSync(exePath).size !== buf.length) writeFileSync(exePath, buf);
    } catch {
        writeFileSync(exePath, buf);
    }
    return exePath;
}

function stopAudioInternal(): void {
    const proc = audioProc;
    audioProc = null;
    audioQueue = [];
    audioQueuedBytes = 0;
    if (proc) {
        try { proc.kill(); } catch { /* ignore */ }
    }
}

/** hwnd из Electron source id "window:<hwnd>:<index>" */
function hwndFromSourceId(id: string): string | null {
    const m = /^window:(\d+):/.exec(id ?? "");
    return m ? m[1] : null;
}

/**
 * Запустить нативный захват звука. mode:
 *   include-window — звук окна (id = Electron source id окна, hwnd -> pid);
 *   exclude-tree   — вся система, кроме дерева процесса Discord (main-процесс = process.pid).
 * Резолвится после "READY" от хелпера (до 4 с) либо с ошибкой.
 */
export async function startAudio(_e: IpcMainInvokeEvent, opts: { mode: string; id?: string }): Promise<P2PAudioStartResult> {
    stopAudioInternal();

    const mode = String(opts?.mode ?? "");
    const id = String(opts?.id ?? "");
    let args: string[];
    if (mode === "include-window") {
        const hwnd = hwndFromSourceId(id);
        if (!hwnd) return { ok: false, error: "источник не является окном" };
        args = ["include-hwnd", hwnd];
    } else if (mode === "exclude-tree") {
        args = ["exclude-pid", String(process.pid)];
    } else {
        return { ok: false, error: `неизвестный режим: ${mode}` };
    }

    let exePath: string;
    try {
        exePath = audioHelperPath();
    } catch (e) {
        return { ok: false, error: `не удалось распаковать хелпер: ${e}` };
    }

    let proc: ReturnType<typeof spawn>;
    try {
        proc = spawn(exePath, args, { stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
    } catch (e) {
        return { ok: false, error: `не удалось запустить хелпер: ${e}` };
    }
    audioProc = proc;
    audioQueue = [];
    audioQueuedBytes = 0;

    return await new Promise<P2PAudioStartResult>(resolve => {
        let settled = false;
        let stderrTail = "";

        const finish = (res: P2PAudioStartResult) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve(res);
        };

        const timer = setTimeout(() => {
            stopAudioInternal();
            finish({ ok: false, error: stderrTail || "хелпер не ответил READY" });
        }, 4000);

        proc.on("error", err => {
            finish({ ok: false, error: `spawn: ${err.message}` });
        });
        proc.on("exit", code => {
            finish({ ok: false, error: stderrTail || `хелпер завершился (код ${code})` });
        });

        proc.stdout?.on("data", (chunk: Buffer) => {
            audioQueue.push(chunk);
            audioQueuedBytes += chunk.length;
            while (audioQueuedBytes > AUDIO_QUEUE_CAP) {
                const dropped = audioQueue.shift()!;
                audioQueuedBytes -= dropped.length;
            }
        });

        proc.stderr?.on("data", (chunk: Buffer) => {
            stderrTail = chunk.toString("utf8").trim().slice(0, 300);
            if (stderrTail === "READY") {
                proc.removeAllListeners("exit");
                finish({ ok: true });
            } else if (stderrTail.startsWith("ERR ")) {
                finish({ ok: false, error: stderrTail.slice(4) });
            }
        });
    });
}

/** Забрать накопившийся PCM (float32 LE 48k stereo) с прошлого вызова. */
export async function pullAudio(): Promise<Uint8Array | null> {
    if (!audioProc || audioQueue.length === 0) return null;
    const buf = audioQueue.length === 1 ? audioQueue[0] : Buffer.concat(audioQueue);
    audioQueue = [];
    audioQueuedBytes = 0;
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
}

/** Остановить нативный захват звука. */
export async function stopAudio(): Promise<void> {
    stopAudioInternal();
}
